import{_ as p,a0 as i,w as d,s as r,I as o,a1 as a,A as e,x as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const R=JSON.parse('{"title":"开始使用 Roland 吧，一款命令行随机选择工具 | LCTT x X-CMD","titleTemplate":false,"description":"开始使用 Roland 吧，一款命令行随机选择工具 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开始使用 Roland 吧，一款命令行随机选择工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开始使用 Roland 吧，一款命令行随机选择工具 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190119 Get started with Roland, a random selection tool for the command line","title":"开始使用 Roland 吧，一款命令行随机选择工具","tag":"201902","desc":""},"relativePath":"201902/20190119 Get started with Roland, a random selection tool for the command line.md","filePath":"[post].md"}'),u={name:"201902/20190119 Get started with Roland, a random selection tool for the command line.md"};function m(f,s,g,c,k,h){const t=i("Link");return d(),r("div",null,[o("p",null,[a(t,{href:"collector:",title:"lujun9972"},{default:e(()=>[...s[0]||(s[0]=[n("#",-1)])]),_:1}),s[2]||(s[2]=n(": author: (Kevin Sonney ",-1)),a(t,{href:"https://opensource.com/users/ksonney"},{default:e(()=>[...s[1]||(s[1]=[n("https://opensource.com/users/ksonney",-1)])]),_:1}),s[3]||(s[3]=n(" (Kevin Sonney))",-1))]),s[24]||(s[24]=l('<h1 id="开始使用-roland-吧-一款命令行随机选择工具" tabindex="-1">开始使用 Roland 吧，一款命令行随机选择工具 <a class="header-anchor" href="#开始使用-roland-吧-一款命令行随机选择工具" aria-label="Permalink to “开始使用 Roland 吧，一款命令行随机选择工具”">​</a></h1><blockquote><p>Roland 可以帮你做出艰难的决定，它是我们在开源工具系列中的第七个工具，将帮助你在 2019 年提高工作效率。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/dice_tabletop_board_gaming_game.jpg?itok=y93eW7HN" alt=""></p><p>每年年初似乎都有疯狂的冲动想提高工作效率。新年的决心，渴望开启新的一年，当然，“抛弃旧的，拥抱新的”的态度促成了这一切。通常这时的建议严重偏向闭源和专有软件，但事实上并不用这样。</p><p>这是我挑选出的 19 个新的（或者对你而言新的）开源工具中的第七个工具来帮助你在 2019 年更有效率。</p><h3 id="roland" tabindex="-1">Roland <a class="header-anchor" href="#roland" aria-label="Permalink to “Roland”">​</a></h3><p>当一周的工作结束后，我唯一想做的就是躺到沙发上打一个周末的游戏。但即使我的职业义务在工作日结束后停止了，但我仍然需要管理我的家庭。洗衣、宠物护理、确保我孩子有他所需要的东西，以及最重要的是：决定晚餐吃什么。</p>',7)),o("p",null,[s[5]||(s[5]=n("像许多人一样，我经常受到",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Decision_fatigue"},{default:e(()=>[...s[4]||(s[4]=[n("决策疲劳",-1)])]),_:1}),s[6]||(s[6]=n("的困扰，根据速度、准备难易程度以及（坦白地说）任何让我压力最小的方式都会导致不太健康的晚餐选择。",-1))]),s[25]||(s[25]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/uploads/roland-1.png",alt:""})],-1)),o("p",null,[a(t,{href:"https://github.com/rjbs/Roland"},{default:e(()=>[...s[7]||(s[7]=[n("Roland",-1)])]),_:1}),s[8]||(s[8]=n(" 让我计划饭菜变得容易。Roland 是一款专为桌面角色扮演游戏设计的 Perl 应用。它从怪物和雇佣者等项目列表中随机挑选。从本质上讲，Roland 在命令行做的事情就像游戏管理员在桌子上掷骰子，以便在《要对玩家做的坏事全书》中找个东西一样。",-1))]),s[26]||(s[26]=l(`<p>通过微小的修改，Roland 可以做得更多。例如，只需添加一张表，我就可以让 Roland 帮我选择晚餐。</p><p>第一步是安装 Roland 及其依赖项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone git@github.com:rjbs/Roland.git</span></span>
<span class="line"><span>cpan install Getopt::Long::Descriptive Moose \\</span></span>
<span class="line"><span>   namespace::autoclean List:AllUtils Games::Dice \\</span></span>
<span class="line"><span>   Sort::ByExample Data::Bucketeer Text::Autoformat \\</span></span>
<span class="line"><span>   YAML::XS</span></span>
<span class="line"><span>cd oland</span></span></code></pre></div><p>接下来，创建一个名为 <code>dinner</code> 的 YAML 文档，并输入我们所有的用餐选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type: list</span></span>
<span class="line"><span>pick: 1</span></span>
<span class="line"><span>items:</span></span>
<span class="line"><span>  - &quot;frozen pizza&quot;</span></span>
<span class="line"><span>  - &quot;chipotle black beans&quot;</span></span>
<span class="line"><span>  - &quot;huevos rancheros&quot;</span></span>
<span class="line"><span>  - &quot;nachos&quot;</span></span>
<span class="line"><span>  - &quot;pork roast&quot;</span></span>
<span class="line"><span>  - &quot;15 bean soup&quot;</span></span>
<span class="line"><span>  - &quot;roast chicken&quot;</span></span>
<span class="line"><span>  - &quot;pot roast&quot;</span></span>
<span class="line"><span>  - &quot;grilled cheese sandwiches&quot;</span></span></code></pre></div><p>运行命令 <code>bin/roland dinner</code> 将读取文件并选择其中一项。</p><p><img src="https://opensource.com/sites/default/files/uploads/roland-2.png" alt=""></p><p>我想提前计划一周，这样我可以提前购买所有食材。 <code>pick</code> 命令确定列表中要选择的物品数量，现在，<code>pick</code> 设置为 1。如果我想计划一周的晚餐菜单，我可以将 <code>pick: 1</code> 变成 <code>pick: 7</code>，它会提供一周的菜单。你还可以使用 <code>-m</code> 选项手动输入选择。</p><p><img src="https://opensource.com/sites/default/files/uploads/roland-3.png" alt=""></p><p>你也可以用 Roland 做些有趣的事情，比如用经典短语添加一个名为 <code>8ball</code> 的文件。</p><p><img src="https://opensource.com/sites/default/files/uploads/roland-4.png" alt=""></p><p>你可以创建各种文件来帮助做出长时间工作后看起来非常难做的常见决策。即使你不用来做这个，你仍然可以用它来为今晚的游戏设置哪个狡猾的陷阱做个决定。</p><hr>`,13)),o("p",null,[s[10]||(s[10]=n("via: ",-1)),a(t,{href:"https://opensource.com/article/19/1/productivity-tools-roland"},{default:e(()=>[...s[9]||(s[9]=[n("https://opensource.com/article/19/1/productivity-tools-roland",-1)])]),_:1})]),o("p",null,[s[15]||(s[15]=n("作者：",-1)),a(t,{href:"https://opensource.com/users/ksonney",title:"Kevin Sonney"},{default:e(()=>[...s[11]||(s[11]=[n("Kevin Sonney",-1)])]),_:1}),s[16]||(s[16]=n(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:e(()=>[...s[13]||(s[13]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),o("p",null,[s[21]||(s[21]=n("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[n("Linux中国",-1)])]),_:1}),s[23]||(s[23]=n(" 荣誉推出",-1))])])}const C=p(u,[["render",m]]);export{R as __pageData,C as default};
